<script setup lang="ts">
import { t } from '../../i18n/index.js';

/**
 * The preview is the sheet itself: the same SVG the printer gets, scaled to the
 * pane. Because the renderer emits absolute millimetres there is nothing to
 * diverge between what is shown here and what comes out of the printer.
 */
defineProps<{
  svg: string;
}>();
</script>

